#!/usr/bin/env python3
"""Crawl the house of hollow houses, save all pages, extract links."""
import re, os, sys, urllib.request, urllib.parse, collections

BASE = "http://house-of-hollow-houses.chal.csaw.io:8000/"
OUT = "/home/ctfplayer/workspace/pages"
os.makedirs(OUT, exist_ok=True)

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except Exception as e:
        return -1, str(e)

def norm(u):
    p = urllib.parse.urlparse(u)
    path = p.path
    if not path.startswith("/"):
        path = "/" + path
    if not path.endswith("/"):
        path += "/"
    return path

seen = set()
q = collections.deque([norm(BASE)])
link_re = re.compile(r'href="([^"]+)"')
comment_re = re.compile(r'<!--(.*?)-->', re.S)

while q:
    path = q.popleft()
    if path in seen:
        continue
    seen.add(path)
    status, body = fetch(BASE.rstrip("/") + path)
    fn = os.path.join(OUT, path.strip("/").replace("/", "_") or "index")
    with open(fn + ".html", "w") as f:
        f.write(f"=== {path} [{status}] ===\n" + body)
    if status != 200:
        print(f"[{status}] {path}")
        continue
    print(f"[200] {path} ({len(body)} bytes)")
    for m in link_re.finditer(body):
        href = m.group(1)
        if href.startswith("http") or href.startswith("data:") or href.startswith("#"):
            continue
        if href.startswith("/"):
            q.append(norm(href))
        else:
            q.append(norm(path + href))

print(f"\nTotal pages crawled: {len(seen)}")
with open(os.path.join(OUT, "list.txt"), "w") as f:
    f.write("\n".join(sorted(seen)))

